const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const ROOT = path.resolve(__dirname, '../../..');
const DEP_MAP_PATH = path.join(ROOT, 'ChatMachines/GeminiSupervisor/dependency-map.json');

function gitBlobSha(relPath) {
  try {
    return execSync(`git rev-parse HEAD:"${relPath}"`, { cwd: ROOT, stdio: ['ignore', 'pipe', 'ignore'] })
      .toString()
      .trim();
  } catch {
    return null;
  }
}

function gitLastCommitSha(relPath) {
  try {
    return execSync(`git log -n 1 --format="%H" -- "${relPath}"`, { cwd: ROOT, stdio: ['ignore', 'pipe', 'ignore'] })
      .toString()
      .trim();
  } catch {
    return null;
  }
}

function parseMarkdownToOrderedArray(content) {
  const normalized = content.replace(/\r\n/g, '\n');
  const rawChunks = normalized.split(/\n{2,}/);
  const elements = [];
  let currentTopic = null;
  let elementIndex = 0;

  for (const chunk of rawChunks) {
    const trimmed = chunk.trim();
    if (!trimmed) continue;
    const headingMatch = trimmed.match(/^(#{1,6})\s+(.+)$/m);
    if (headingMatch) {
      currentTopic = headingMatch[2].trim();
    }
    elements.push({
      type: 'content',
      index: elementIndex++,
      topic: currentTopic,
      text: trimmed
    });
  }
  return elements;
}

function parseJsonToOrderedArray(content) {
  const parsed = JSON.parse(content);
  const elements = [];
  let elementIndex = 0;

  function walk(node, currentPath) {
    if (Array.isArray(node)) {
      elements.push({
        type: 'structural',
        index: elementIndex++,
        path: currentPath,
        container: 'array',
        length: node.length
      });
      node.forEach((item, idx) => walk(item, `${currentPath}[${idx}]`));
    } else if (node !== null && typeof node === 'object') {
      const keys = Object.keys(node);
      elements.push({
        type: 'structural',
        index: elementIndex++,
        path: currentPath,
        container: 'object',
        keys
      });
      for (const k of keys) {
        walk(node[k], currentPath ? `${currentPath}.${k}` : k);
      }
    } else {
      elements.push({
        type: 'primitive',
        index: elementIndex++,
        path: currentPath,
        value: node
      });
    }
  }

  walk(parsed, '$');
  return elements;
}

function buildStableReader(sourcePath, fullContent) {
  const ext = path.extname(sourcePath).toLowerCase();
  if (ext === '.json') {
    return parseJsonToOrderedArray(fullContent);
  }
  return parseMarkdownToOrderedArray(fullContent);
}

function main() {
  if (!fs.existsSync(DEP_MAP_PATH)) {
    console.error(`Dependency map not found at ${DEP_MAP_PATH}`);
    process.exit(1);
  }

  const depMap = JSON.parse(fs.readFileSync(DEP_MAP_PATH, 'utf8'));
  let mutated = false;

  for (const [depKey, entry] of Object.entries(depMap.dependencies)) {
    if (entry.type !== 'truth_readable_document') continue;

    const fullSourcePath = path.join(ROOT, entry.canonical_path);
    if (!fs.existsSync(fullSourcePath)) {
      console.warn(`[sync-readers] Canonical source not found: ${entry.canonical_path}`);
      continue;
    }

    const currentBlobSha = gitBlobSha(entry.canonical_path);
    const currentCommitSha = gitLastCommitSha(entry.canonical_path);
    const fullReaderPath = path.join(ROOT, entry.reader_path);
    const readerExists = fs.existsSync(fullReaderPath);

    const needsRebuild = !readerExists ||
      entry.source_blob_sha !== currentBlobSha ||
      entry.source_commit_sha !== currentCommitSha;

    if (needsRebuild) {
      console.log(`[sync-readers] Rebuilding stable reader for ${depKey} (${entry.canonical_path})`);
      const sourceContent = fs.readFileSync(fullSourcePath, 'utf8');
      const readerArray = buildStableReader(entry.canonical_path, sourceContent);

      const readerDir = path.dirname(fullReaderPath);
      if (!fs.existsSync(readerDir)) {
        fs.mkdirSync(readerDir, { recursive: true });
      }

      fs.writeFileSync(fullReaderPath, JSON.stringify(readerArray, null, 2) + '\n');
      const newReaderBlobSha = gitBlobSha(entry.reader_path) || '';

      entry.source_blob_sha = currentBlobSha || '';
      entry.source_commit_sha = currentCommitSha || '';
      entry.reader_blob_sha = newReaderBlobSha;
      entry.item_count = readerArray.length;
      entry.last_synced_at = new Date().toISOString();
      mutated = true;
    } else {
      console.log(`[sync-readers] Up to date: ${depKey}`);
    }
  }

  if (mutated) {
    fs.writeFileSync(DEP_MAP_PATH, JSON.stringify(depMap, null, 2) + '\n');
    console.log('[sync-readers] Updated dependency-map.json successfully.');
  } else {
    console.log('[sync-readers] No reader updates needed.');
  }
}

main();

